const { prisma } = await app("lib/prisma.ts");
const { createFeedbackAction } = await app("lib/actions/feedback.ts");
const { requireUser } = await app("lib/workspace.ts");

// Create a user and workspace with membership and webhookUrl to simulate slow webhook
const user = await prisma.user.create({ data: { email: "user@example.com", name: "Test User", passwordHash: "hash" } });
const workspace = await prisma.workspace.create({ data: { name: "Test Workspace", slug: "test-workspace", webhookUrl: "http://127.0.0.1:0/slow-webhook", webhookSecret: "secret" } });
await prisma.membership.create({ data: { userId: user.id, workspaceId: workspace.id, role: "ADMIN" } });

// Set session to simulate signed-in user
set_session({ user: { id: user.id, email: user.email, name: user.name } });

// Prepare a valid FormData for feedback submission
const formData = new FormData();
formData.set("title", "Test Feedback Title");
formData.set("body", "This is a test feedback body without URL.");

const workspaceSlug = workspace.slug;
const prevState = {};
const validFormData = formData;

// Setup a local HTTP server to simulate a slow webhook endpoint
const http = await import("node:http");

let server;
let port;

async function startSlowWebhookServer() {
  return new Promise((resolve) => {
    server = http.createServer((req, res) => {
      // Delay response for 8 seconds to simulate slow webhook
      setTimeout(() => {
        res.writeHead(200, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ success: true }));
      }, 8000);
    });
    server.listen(0, "127.0.0.1", () => {
      port = server.address().port;
      resolve();
    });
  });
}

await startSlowWebhookServer();

// Override workspace webhookUrl to use the local slow webhook server
await prisma.workspace.update({ where: { id: workspace.id }, data: { webhookUrl: `http://127.0.0.1:${port}/slow-webhook` } });

// Cleanup function to close server after tests
async function stopSlowWebhookServer() {
  return new Promise((resolve) => {
    server.close(() => resolve());
  });
}

// Expose stop function for tests
globalThis.stopSlowWebhookServer = stopSlowWebhookServer;

